using System;
using System.Linq;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static void FreshSocialInspect(){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && peer.Entity.Class==20 && peer.Entity.Level>=130 && p.Entity.Level>=130);
        Require(FreshClassSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_class_probe WHERE stage=2")));
        System.Console.WriteLine("[fresh-social] profiles="+Sql("SELECT json_agg(r ORDER BY uid)::text FROM (SELECT uid,name,body,spouse,level,conquerpoints FROM entities WHERE uid=ANY(@uids))r","uids",players.Concat(new[]{peer}).Select(w=>(long)w.Entity.UID).ToArray()));
        System.Console.WriteLine("[fresh-social] gifts="+Sql("SELECT coalesce(json_agg(r ORDER BY entityid,uid)::text,'[]') FROM (SELECT entityid,uid,id,stacksize,warehouse FROM items WHERE entityid=ANY(@uids) AND id BETWEEN 751000 AND 758999)r","uids",players.Concat(new[]{peer}).Select(w=>(long)w.Entity.UID).ToArray()));
        System.Console.WriteLine("[fresh-social] leaders="+Sql("SELECT coalesce(json_agg(r ORDER BY category)::text,'[]') FROM (SELECT g.category,max(f.totals[g.category]) AS maximum FROM revora_flower_balances f JOIN entities e ON e.uid=f.uid CROSS JOIN generate_series(1,4) AS g(category) WHERE e.body IN(2001,2002,2005,2006) GROUP BY g.category)r"));
        System.Console.WriteLine("[career-process] career-fresh-social-inspect-passed");System.Console.Out.Flush();Environment.Exit(0);
    }

    static string FreshSocialSnapshot(GameState p,GameState[] players,GameState peer){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'profiles',(SELECT json_agg(r ORDER BY uid) FROM (SELECT uid,body,spouse FROM entities WHERE uid=ANY(@uids))r),'flowers',(SELECT json_agg(r ORDER BY uid) FROM revora_flower_balances r WHERE uid=ANY(@uids)),'gifts',(SELECT json_agg(r ORDER BY created_at,id) FROM revora_flower_deliveries r WHERE sender=ANY(@uids) OR recipient=ANY(@uids)))::text","prior",FreshClassSnapshot(p,players,peer),"uids",new long[]{p.Entity.UID,peer.Entity.UID}));}
    static void FreshSocialSave(GameState p,GameState[] players,GameState peer,int step){foreach(var who in players.Concat(new[]{peer}))Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_social_probe SET step=@step,snapshot=@snapshot","step",step,"snapshot",FreshSocialSnapshot(p,players,peer));}
    static void FreshSocialJourney(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && peer.Entity.Class==20 && peer.Entity.Level>=130 && p.Entity.Level>=130);

        DateTime now=new DateTime(2041,10,2,18,0,0,DateTimeKind.Utc);var flowerTime=CandidateFlowerClock();if(flowerTime>now)now=flowerTime;Feature("FlowerDelivery").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        bool first=(bool)Sql("SELECT to_regclass('revora_fresh_social_probe') IS NULL");if(first)Require(phase.EndsWith("flowers") && FreshClassSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_class_probe WHERE stage=2")));
        Call(Feature("FlowerDelivery"),"Load",p);Call(Feature("FlowerDelivery"),"Load",peer);
        if(first){Require(p.Entity.Body==1003 && peer.Entity.Body==2001 && p.Entity.Spouse=="None" && peer.Entity.Spouse=="None");Sql("CREATE TABLE revora_fresh_social_probe(step int,snapshot text);INSERT INTO revora_fresh_social_probe VALUES(0,NULL)");FreshSocialSave(p,players,peer,0);}
        Require(FreshSocialSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_social_probe")));int step=(int)Sql("SELECT step FROM revora_fresh_social_probe");
        if(phase.EndsWith("flowers")){
            Require(step>=0 && step<4);p.Entity.Teleport(1002,400,350);peer.Entity.Teleport(1002,400,351);
            while(step<4){uint gift=0;
                if(step==1){uint cp=p.Entity.ConquerPoints;var old=p.Inventory.Objects.Select(i=>i.UID).ToArray();CareerBuy(p,752999);var item=p.Inventory.Objects.Single(i=>!old.Contains(i.UID));Require(item.ID==752999 && p.Entity.ConquerPoints==cp-ConquerItemInformation.BaseInformations[752999].ConquerPointsWorth);gift=item.UID;}
                if(step>=2){now=now.AddDays(1);var magnolia=Feature("MagnoliaQuest");magnolia.GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));magnolia.GetField("SeedRoll",Hidden).SetValue(null,(Func<int,int>)(max=>80));int bonus=step==2?1:2;magnolia.GetField("BonusRoll",Hidden).SetValue(null,(Func<int,int>)(max=>max==100?0:bonus));HeartTalk(p,79882,5);Require(p.Entity.MapID==1806);HeartTalk(p,44100,1);HeartTalk(p,44100,3);Require(p.Inventory.Objects.Any(i=>i.ID==729306));uint cp=p.Entity.ConquerPoints;HeartTalk(p,44100,5);HeartTalk(p,44100,6);Require(p.Entity.ConquerPoints==cp-1);var seed=p.Inventory.Objects.Single(i=>i.ID==729308);uint expected=step==2?753003u:754001u;p.Entity.X=98;p.Entity.Y=111;ItemHandler.UseItem(seed,p);var flower=p.Inventory.Objects.Single(i=>i.ID==expected);Require(!p.Inventory.ContainsUID(seed.UID));gift=flower.UID;HeartTalk(p,44100,2);Require(p.Entity.MapID==1002);}
                p.Entity.Teleport(1002,400,350);peer.Entity.Teleport(1002,400,351);var packet=new byte[24];Revora.Network.Writer.WriteUInt16(16,0,packet);Revora.Network.Writer.WriteUInt16(1150,2,packet);Revora.Network.Writer.WriteUInt32(peer.Entity.UID,8,packet);Revora.Network.Writer.WriteUInt32(gift,12,packet);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,16,packet);Revora.Network.PacketHandler.HandlePacket(packet,p);Require((long)Sql("SELECT count(*) FROM revora_flower_deliveries WHERE sender=@sender AND recipient=@recipient","sender",(long)p.Entity.UID,"recipient",(long)peer.Entity.UID)==step+1 && (gift==0 || !p.Inventory.ContainsUID(gift)));string saved=FreshSocialSnapshot(p,players,peer);Revora.Network.PacketHandler.HandlePacket(packet,p);Require(saved==FreshSocialSnapshot(p,players,peer));FreshSocialSave(p,players,peer,++step);
            }
        }else if(phase.EndsWith("marry")){
            Require(step==4 && p.Entity.Spouse=="None" && peer.Entity.Spouse=="None");p.Entity.Teleport(1002,400,350);peer.Entity.Teleport(1002,400,351);new Revora.Game.Attacking.Handle(new Attack(true){AttackType=Attack.MarriageRequest,Attacker=p.Entity.UID,Attacked=peer.Entity.UID},p.Entity,null);new Revora.Game.Attacking.Handle(new Attack(true){AttackType=Attack.MarriageAccept,Attacker=peer.Entity.UID,Attacked=p.Entity.UID},peer.Entity,null);Require(p.Entity.Spouse==peer.Entity.Name && peer.Entity.Spouse==p.Entity.Name);FreshSocialSave(p,players,peer,5);
        }else Require(phase.EndsWith("reload") && step==5);
        Require((long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=ANY(@uids) AND achievement_id=10127 AND source='flower-delivery-v1'","uids",new long[]{p.Entity.UID,peer.Entity.UID})==2 && (bool)Sql("SELECT totals=ARRAY[1,999,3,1]::bigint[] FROM revora_flower_balances WHERE uid=@uid","uid",(long)peer.Entity.UID));Require(peer.Entity.MyFlowers.RedRoses==1 && peer.Entity.MyFlowers.Lilies==999 && peer.Entity.MyFlowers.Orchads==3 && peer.Entity.MyFlowers.Tulips==1);
        if(!phase.EndsWith("flowers")){Require(p.Entity.Spouse==peer.Entity.Name && peer.Entity.Spouse==p.Entity.Name && (long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=ANY(@uids) AND achievement_id=10129","uids",new long[]{p.Entity.UID,peer.Entity.UID})==2);string saved=FreshSocialSnapshot(p,players,peer);new Revora.Game.Attacking.Handle(new Attack(true){AttackType=Attack.MarriageAccept,Attacker=peer.Entity.UID,Attacked=p.Entity.UID},peer.Entity,null);Require(saved==FreshSocialSnapshot(p,players,peer));}
        Require(FreshSocialSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_social_probe")));System.Console.WriteLine("[career-process] "+phase+"-passed step="+Sql("SELECT step FROM revora_fresh_social_probe"));System.Console.Out.Flush();Environment.Exit(0);
    }
}
